/// Cross-platform parity test: verifies that the Dart validator produces
/// identical findViolations output as the TypeScript engine for the same
/// grid/edge inputs. Fixtures are generated by scripts/gen-validator-fixtures.ts
/// and committed at packages/engine/test-fixtures/validator.json.
library;

import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:halve/data/models/puzzle.dart';
import 'package:halve/engine/validator.dart';

void main() {
  late List<dynamic> fixtures;

  setUpAll(() {
    // CWD when flutter test runs is apps/mobile/; step up two levels to the repo root.
    final file = File('../../packages/engine/test-fixtures/validator.json');
    fixtures = jsonDecode(file.readAsStringSync()) as List<dynamic>;
  });

  group('validator parity (Dart ↔ TS engine)', () {
    for (var i = 0; i < 15; i++) {
      // Bind index at loop time to avoid closure capture issues.
      final idx = i;
      test('fixture $idx', () {
        final raw = fixtures[idx] as Map<String, dynamic>;
        final description = raw['description'] as String;
        final grid = _parseGrid(raw['grid']);
        final edges = _parseEdges(raw['edges']);
        final expectedSet = Set<String>.from(
          (raw['violations'] as List<dynamic>).cast<String>(),
        );

        final dartViolations = findViolations(grid, edges);
        final dartSet =
            dartViolations.map((c) => '${c.$1}-${c.$2}').toSet();

        expect(dartSet, equals(expectedSet),
            reason: 'fixture "$description" (index $idx) mismatch');
      });
    }
  });
}

Grid _parseGrid(dynamic raw) {
  final rows = raw as List<dynamic>;
  return rows.map<List<Cell>>((row) {
    final cells = row as List<dynamic>;
    return cells
        .map<Cell>((v) => v == null ? null : (v as int))
        .toList();
  }).toList();
}

List<Edge> _parseEdges(dynamic raw) {
  final list = raw as List<dynamic>;
  return list
      .map((e) => Edge.tryFromJson(e as Map<String, dynamic>))
      .whereType<Edge>()
      .toList();
}
